insert into slime_skills (id, name, wiki_title, tier_group, tier_wiki, wiki_categories, scope, noncanon_page, aliases, effect, wiki_url, source, in_unique_pool) values
  ('abaddon', 'Abaddon', 'Abaddon', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Destruction','Lord of Annihilation','Lord of Extinction']::text[], 'Lets the user''s attacks disrupt spatial abilities and bypass Distortion Field; an evolution of Sandalphon.', 'https://tensura.fandom.com/wiki/Abaddon', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('absolute_end', 'Absolute End', 'Absolute End', 'unique', 'Art / Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Absolute Severance']::text[], 'Severs space so that magical and physical phenomena overwhelm the target; strong enough to hurt a True Dragon.', 'https://tensura.fandom.com/wiki/Absolute_End', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('adapter', 'Adapter', 'Adapter', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Disguiser','Impersonator']::text[], 'Lets the user take the form of anyone they have seen, but a much stronger target can only be imitated partially. Slightly weaker than Imitator.', 'https://tensura.fandom.com/wiki/Adapter', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('agastya', 'Agastya', 'Agastya', 'ultimate', 'Ultimate enchantment', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Book of Prophecy']::text[], 'Information-type ability: foresees a few seconds ahead and can make an opponent believe false things for a short time, though it cannot rewrite information and can be resisted.', 'https://tensura.fandom.com/wiki/Agastya', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('agni', 'Agni', 'Agni', 'ultimate', 'Ultimate enchantment', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Blaze','Lord of Flame']::text[], 'Exact abilities unspecified; appears to produce and control flame to an extreme degree and may inherit part of Raguel.', 'https://tensura.fandom.com/wiki/Agni', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('ahura_mazda', 'Ahura Mazda', 'Ahura Mazda', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Radiance','Lord of Good Light','Lord of Light and Virtue','Lord of Virtuous Light']::text[], 'Described as the direct opposite of Angra Mainyu in authority, able to counter its abilities.', 'https://tensura.fandom.com/wiki/Ahura_Mazda', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('all_of_creation', 'All of Creation', 'All of Creation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, '{}'::text[], 'Understand all non-hidden phenomena witnessed', 'https://tensura.fandom.com/wiki/All_of_Creation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('all_rounder', 'All-Rounder', 'All-Rounder', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Universal One']::text[], 'Like Usurper but for arts: after analysing a target, their arts can be copied, though mastery still needs training because experience is not copied.', 'https://tensura.fandom.com/wiki/All-Rounder', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('all_seeing_eye', 'All-Seeing Eye', 'All-Seeing Eye', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Sky Eye','Celestial Eyes','Divine Eye']::text[], 'Ocular Extra skill giving 360-degree vision and faster reactions.', 'https://tensura.fandom.com/wiki/All-Seeing_Eye', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('alternative', 'Alternative', 'Alternative', 'ultimate', 'Ultimate enchantment', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Agent Prerogative']::text[], 'Borrowed Ultimate-grade power whose effects vary by user. Less energy-efficient than natural Ultimates and compels the user to obey the owner of Michael.', 'https://tensura.fandom.com/wiki/Alternative', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('amalthea', 'Amalthea', 'Amalthea', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Game only', true, ARRAY['Mother of Mirror Realm']::text[], 'Gives total control over the Mirror World (made as large as the Central World), including changing its laws; weaker when the user is outside it.', 'https://tensura.fandom.com/wiki/Amalthea', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('amaterasu', 'Amaterasu', 'Amaterasu', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Shimmering Flame','Lord of Heat']::text[], 'Purest form of the Formhide technique: the body becomes haze so all attacks pass through; its second aspect involves sunlight-based power.', 'https://tensura.fandom.com/wiki/Amaterasu', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('amon', 'Amon', 'Amon', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Avarice','Aamon']::text[], 'Abilities currently unknown.', 'https://tensura.fandom.com/wiki/Amon', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('analyst', 'Analyst', 'Analyst', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Analysis','Analyzer','Parser']::text[], 'Effect text not clear in the extract; see the wiki page.', 'https://tensura.fandom.com/wiki/Analyst', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('analytical_appraisal', 'Analytical Appraisal', 'Analytical Appraisal', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Analyze and Appraise','Analyze and Assess','Appraising Analyzation']::text[], 'Analyse objects and people', 'https://tensura.fandom.com/wiki/Analytical_Appraisal', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('angra_mainyu', 'Angra Mainyu', 'Angra Mainyu', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Vice','Anra Manyu','King of Evil','Lord of Evil','Lord of Vileness','Lord of Vulgarity','Vile King','Vulgar King']::text[], 'Embodies the will to kill god and feeds on resentment; specialises in creation and research and has a sure-kill power reducing things to nothing, with an Eternity attribute.', 'https://tensura.fandom.com/wiki/Angra_Mainyu', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('appraisal_eye', 'Appraisal Eye', 'Appraisal Eye', 'extra', NULL, ARRAY['Extra']::text[], NULL, false, '{}'::text[], 'Ocular Extra skill with effects similar to Analytical Appraisal.', 'https://tensura.fandom.com/wiki/Appraisal_Eye', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('armor_fusion', 'Armor Fusion', 'Armor Fusion', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Identify Armor','Unify Armor']::text[], 'Merges the user''s body with the armor they wear.', 'https://tensura.fandom.com/wiki/Armor_Fusion', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('artist', 'Artist', 'Artist', 'ultimate', 'Ultimate gift', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Authentic Writer']::text[], 'Imitates the powers and arts of anyone the user knew at their peak and layers them over the user''s own power.', 'https://tensura.fandom.com/wiki/Artist', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('asmodeus', 'Asmodeus', 'Asmodeus', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Lust','Ruler of Lust']::text[], 'Command the passage of life and death; sees life force; sub-skill Life Domination', 'https://tensura.fandom.com/wiki/Asmodeus', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('astaroth', 'Astaroth', 'Astaroth', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Fallen']::text[], 'Very strong power combining Astarte''s creation and destruction power with Belphegor''s absolute superiority over the mind.', 'https://tensura.fandom.com/wiki/Astaroth', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('astarte', 'Astarte', 'Astarte', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Heaven','Lord of High Heaven']::text[], 'Praised even by Veldanava; lets the user steer skill evolution in a desired direction, even turning Unique skills into Ultimates if there is enough energy.', 'https://tensura.fandom.com/wiki/Astarte', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('avenger', 'Avenger', 'Avenger', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Game only', true, ARRAY['Hater']::text[], 'Lets the user partly gain the skills of opponents who defeated them.', 'https://tensura.fandom.com/wiki/Avenger', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('awakener', 'Awakener', 'Awakener', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Game only', true, ARRAY['Awakened']::text[], 'Strengthening skill that lets the user break their limits; its first user evolved into a spiritual life-form and stabilised her existence as an Artifact archangel.', 'https://tensura.fandom.com/wiki/Awakener', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('azathoth', 'Azathoth', 'Azathoth', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['God of the Void','Lord of the Void']::text[], 'Result of Raphael merging with Beelzebuth', 'https://tensura.fandom.com/wiki/Azathoth', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('azazel', 'Azazel', 'Azazel', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Temptation']::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Azazel', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('azi_dahaka', 'Azi Dahaka', 'Azi Dahaka', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Evil Dragons','Azhi Dahaka','Azhdahak']::text[], 'Its nature is assimilating power absorbed from a target.', 'https://tensura.fandom.com/wiki/Azi_Dahaka', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('azrael', 'Azrael', 'Azrael', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Salvation']::text[], 'Abilities unknown, but described as extremely powerful.', 'https://tensura.fandom.com/wiki/Azrael', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('bahamut', 'Bahamut', 'Bahamut', 'ultimate', 'Ultimate gift', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Mythical Beasts','Lord of Fantastic Beasts','Lord of Phantom Beasts','Lord of Beasts']::text[], 'Controls natural influences, can interfere with planets and manipulate gravity over a wide area.', 'https://tensura.fandom.com/wiki/Bahamut', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('beelzebub', 'Beelzebub', 'Beelzebub', 'ultimate', 'Ultimate gift', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Gourmet','Belzebuth','Beelzebub, Lord of Gastronomy']::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Beelzebub', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('beelzebuth', 'Beelzebuth', 'Beelzebuth', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Gluttony','Beelzebub','Belzebuth']::text[], 'Devour / food-chain effects', 'https://tensura.fandom.com/wiki/Beelzebuth', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('belial', 'Belial', 'Belial', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of the Underworld','Lord of Death','Lord of Death World','Lord of Dark World','Lord of the Dead World','Lord of the World of the Dead']::text[], 'The power closest to death: lets the user control the Nihilistic World and use Nihility (even Nihility Collapse) safely within limits.', 'https://tensura.fandom.com/wiki/Belial', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('belphegor', 'Belphegor', 'Belphegor', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Sloth']::text[], 'Pair: Sariel', 'https://tensura.fandom.com/wiki/Belphegor', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('berserk', 'Berserk', 'Berserk', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Unequaled Strength','Indiscriminate','Senseless','Total Chaos']::text[], 'Exact nature unknown; greatly raises physical strength in proportion to the user''s rage.', 'https://tensura.fandom.com/wiki/Berserk', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('berserker', 'Berserker', 'Berserker', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Delinquent','Thug','Ruffian']::text[], 'Greatly boosts overall physical ability and removes the brain''s natural limiter, with durability high enough to avoid lasting injury.', 'https://tensura.fandom.com/wiki/Berserker', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('bewilder', 'Bewilder', 'Bewilder', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, '{}'::text[], 'Turns the user''s intentions into voice-borne waves that interfere with others'' brainwaves, for subliminal messages or direct commands; blockable if the waves are analysed and countered with matching aura.', 'https://tensura.fandom.com/wiki/Bewilder', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('black_flame', 'Black Flame', 'Black Flame', 'extra', 'Extra skill / Storm magic', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Dark Flame']::text[], 'Higher form of Flame Transformation from Veldora: converts internal magicules into super-heated flame without the body''s limits and controls it freely.', 'https://tensura.fandom.com/wiki/Black_Flame', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('black_lightning', 'Black Lightning', 'Black Lightning', 'extra', 'Extra skill / Intrinsic skill / Storm magic', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Dark Lightning']::text[], 'Degraded Dark Lightning that is still among the strongest offensive magic; needs a conduit to tune aim and power.', 'https://tensura.fandom.com/wiki/Black_Lightning', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('black_thunder', 'Black Thunder', 'Black Thunder', 'extra', 'Extra skill / Storm magic', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Dark Thunder']::text[], 'Perfected Black Lightning that needs no conduit; controlled directly through the user''s mana with very fine tuning.', 'https://tensura.fandom.com/wiki/Black_Thunder', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('blade_transformation', 'Blade Transformation', 'Blade Transformation', 'ultimate', 'Ultimate gift', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Blade Transform']::text[], 'Lets Agera turn into a sword and pass all his experience and mastered arts to the wielder.', 'https://tensura.fandom.com/wiki/Blade_Transformation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('body_armor', 'Body Armor', 'Body Armor', 'common', 'Intrinsic skill / Common skill', ARRAY['Common']::text[], 'Main story', false, '{}'::text[], 'Forms a shell harder than steel on chosen body parts using ambient magicules; its grade depends on the user''s power.', 'https://tensura.fandom.com/wiki/Body_Armor', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('body_double', 'Body Double', 'Body Double', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Doppelganger','Replication']::text[], 'Creates linked copies of the user; number and magicule amount depend on proficiency and magicules spent, and more magicules per copy means fewer copies.', 'https://tensura.fandom.com/wiki/Body_Double', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('carnation', 'Carnation', 'Carnation', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Game only', true, ARRAY['Gluttony']::text[], 'Game-original evolution after becoming a serpent slime', 'https://tensura.fandom.com/wiki/Carnation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('celestial_eye', 'Celestial Eye', 'Celestial Eye', 'extra', NULL, ARRAY['Extra']::text[], NULL, false, '{}'::text[], 'Ocular skill rivalling or exceeding Heavenly Eye: sees in nearly any condition and directly perceives magicules and spiritual matter.', 'https://tensura.fandom.com/wiki/Celestial_Eye', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('chant_annulment', 'Chant Annulment', 'Chant Annulment', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Cast Cancel','Chant Cancelation']::text[], 'Cast known magic without chanting', 'https://tensura.fandom.com/wiki/Chant_Annulment', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('charm', 'Charm', 'Charm', 'extra', 'Extra skill / Intrinsic skill / Illusion magic', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Beguile','Seduce']::text[], 'Hypnotises and briefly controls a target''s thoughts and can alter memories; the effect can linger and returns if the cleansing is undone.', 'https://tensura.fandom.com/wiki/Charm', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('chef', 'Chef', 'Chef', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Cook','Fusionist']::text[], 'Heals any injury by ''cooking'' it.', 'https://tensura.fandom.com/wiki/Chef', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('chosen_one', 'Chosen One', 'Chosen One', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Champion''s Ambition','Chosen Champion','Hero''s Ambition']::text[], 'Near-Ultimate power that turns a battle in the user''s favour just by being active; only holders of a Unique or Ultimate skill can resist its manipulative side.', 'https://tensura.fandom.com/wiki/Chosen_One', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('coercion', 'Coercion', 'Coercion', 'common', 'Intrinsic skill / Common skill', ARRAY['Common']::text[], 'Main story', false, ARRAY['Menace']::text[], 'Projects vocal pressure on one or many targets to force compliance or intimidate; can be resisted by strong will or countered with another Coercion or a form of Haki.', 'https://tensura.fandom.com/wiki/Coercion', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('combatant', 'Combatant', 'Combatant', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Battler','Fighter','Martial Artist']::text[], 'Lets the user master any weapon, fighting style or art they learn in the Central World.', 'https://tensura.fandom.com/wiki/Combatant', 'Wiki API fetch 2026-10-15 (skill pages)', true);
insert into slime_skills (id, name, wiki_title, tier_group, tier_wiki, wiki_categories, scope, noncanon_page, aliases, effect, wiki_url, source, in_unique_pool) values
  ('commander', 'Commander', 'Commander', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Grand Marshal','Born Leader','Generalissimo','Leader']::text[], 'Keeps Benimaru calm and efficient in battle, lets him sense the flow of power among his forces and read his odds of victory, and boosts his army.', 'https://tensura.fandom.com/wiki/Commander', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('cook', 'Cook', 'Cook', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Decider','Master Chef','Judgement']::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Cook', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('corrosion', 'Corrosion', 'Corrosion', 'common', 'Common skill', ARRAY['Common']::text[], 'Main story', false, ARRAY['Decomposition','Erosion','Rot']::text[], 'Corrodes anything the user touches, breaking down living tissue and equipment; can also be added to attacks.', 'https://tensura.fandom.com/wiki/Corrosion', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('craftsman', 'Craftsman', 'Craftsman', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Divine Craftsman','Artisan','Master','Mastercraft']::text[], 'Enhanced Researcher: greatly raises analysis, processing speed and technical mastery for crafting, material assessment and weapon forging.', 'https://tensura.fandom.com/wiki/Craftsman', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('creator', 'Creator', 'Creator', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Initiator']::text[], 'Reshapes the user''s own soul energy into whatever is needed, limited by the amount of desire; used to build abilities such as Anti-skill and to evolve the user''s body.', 'https://tensura.fandom.com/wiki/Creator', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('cthugha', 'Cthugha', 'Cthugha', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Divine Flames','Lord of Flame God']::text[], 'Locates any designated being and lets the user reach them across any distance, even beyond space and time.', 'https://tensura.fandom.com/wiki/Cthugha', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('cthulhu', 'Cthulhu', 'Cthulhu', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Divine Ice']::text[], 'Optimised merger of Gabriel and Leviathan with far greater power: keeps Fixation and Absorption, giving unmatched defence and energy absorption.', 'https://tensura.fandom.com/wiki/Cthulhu', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('danger_detection', 'Danger Detection', 'Danger Detection', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, '{}'::text[], 'Senses dangers such as traps or strong opponents.', 'https://tensura.fandom.com/wiki/Danger_Detection', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('decipherer', 'Decipherer', 'Decipherer', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, '{}'::text[], 'Reads the thoughts and feelings of a touched target and reads movement, mana flow and signs of magic.', 'https://tensura.fandom.com/wiki/Decipherer', 'Wiki API fetch 2026-10-15 (skill pages)', true),
