  ('deus_ex_machina', 'Deus Ex Machina', 'Deus Ex Machina', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Machine Gods','Lord of Divine Machines','Lord of Machine Divinity']::text[], 'Inherits Reverser and adds mineral control (with Earth Element Manipulation), letting Beretta turn her body into mineral forms with total mineral control.', 'https://tensura.fandom.com/wiki/Deus_Ex_Machina', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('dilettante', 'Dilettante', 'Dilettante', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Omniphile']::text[], 'Analyses the properties and components of items, their age and their quality.', 'https://tensura.fandom.com/wiki/Dilettante', 'Wiki API fetch 2026-10-15 (skill pages)', true),
