  ('divine_strength', 'Divine Strength', 'Divine Strength', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Divine Force']::text[], 'Strengthening skill that drastically raises physical ability.', 'https://tensura.fandom.com/wiki/Divine_Strength', 'Wiki API fetch 2026-10-15 (skill pages)', false),
