  ('earth_manipulation', 'Earth Manipulation', 'Earth Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Control Earth']::text[], 'Manipulates and uses the Earth element.', 'https://tensura.fandom.com/wiki/Earth_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('eminence', 'Eminence', 'Eminence', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Exalted One','Honored One','Venerated One']::text[], 'Creates a barrier that traps opponents and turns the enclosed space in the user''s favour.', 'https://tensura.fandom.com/wiki/Eminence', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('engorger', 'Engorger', 'Engorger', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Amplifier','Increaser']::text[], 'Amplifies the momentum of anything, accelerating the user and attacks or boosting body mass for devastating melee.', 'https://tensura.fandom.com/wiki/Engorger', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('enhanced_body_double', 'Enhanced Body Double', 'Enhanced Body Double', 'extra', 'Extra skill / Intrinsic skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Enhanced Replication']::text[], 'A sturdier Body Double, good enough to serve as an incarnation vessel for True Dragons.', 'https://tensura.fandom.com/wiki/Enhanced_Body_Double', 'Wiki API fetch 2026-10-15 (skill pages)', false),
