  ('explosive_flames', 'Explosive Flames', 'Explosive Flames', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, '{}'::text[], 'Creates explosive flames.', 'https://tensura.fandom.com/wiki/Explosive_Flames', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('falsifier', 'Falsifier', 'Falsifier', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Deceiver','Trickster']::text[], 'Deceives others'' senses to create a false reality only the user knows, e.g. a spear looks like a knife.', 'https://tensura.fandom.com/wiki/Falsifier', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('farsight', 'Farsight', 'Farsight', 'common', NULL, ARRAY['Common']::text[], NULL, false, '{}'::text[], 'Enhanced long-distance vision.', 'https://tensura.fandom.com/wiki/Farsight', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('faust', 'Faust', 'Faust', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Investigation','Lord of Inquiry']::text[], 'Essence is reaching the ultimate truth; Veldora''s Ultimate skill that later became Nyarlathotep.', 'https://tensura.fandom.com/wiki/Faust', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('flame_domination', 'Flame Domination', 'Flame Domination', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Flame and Heat Domination','Fire Domination','Dominate Flame']::text[], 'Total control over fire and flame elements.', 'https://tensura.fandom.com/wiki/Flame_Domination', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('flame_manipulation', 'Flame Manipulation', 'Flame Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Flame and Heat Manipulation','Fire Manipulation','Control Flame','Heat Manipulation']::text[], 'Shapes and alters existing flames and controls the user''s body heat; cannot create fire from nothing but can concentrate heat on a point.', 'https://tensura.fandom.com/wiki/Flame_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('fortuna', 'Fortuna', 'Fortuna', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Odds','Lord of Adversity','Lord of Fate']::text[], 'Predicts the future with greater accuracy than Future Attack Prediction.', 'https://tensura.fandom.com/wiki/Fortuna', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('frenzy', 'Frenzy', 'Frenzy', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Berserker','Berserker Rage']::text[], 'More than doubles physical strength and speed at the cost of magicules; inexperienced users lose their sanity.', 'https://tensura.fandom.com/wiki/Frenzy', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('full_body_armorize', 'Full Body Armorize', 'Full Body Armorize', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Armorize Body']::text[], 'Armorizes the user''s whole body.', 'https://tensura.fandom.com/wiki/Full_Body_Armorize', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('fusion', 'Fusion', 'Fusion', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Unification','Unify','Union']::text[], 'Lets the user physically merge with allies they bond with, boosting combined strength (goblin riders merge to move on all fours at about Rank A-minus).', 'https://tensura.fandom.com/wiki/Fusion', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('fusionist', 'Fusionist', 'Fusionist', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Mixer']::text[], 'Fuses matter in a small area to cause an explosion, comparable to nuclear magic at best but dangerous to the user and allies.', 'https://tensura.fandom.com/wiki/Fusionist', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('future_attack_prediction', 'Future Attack Prediction', 'Future Attack Prediction', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Predict Future Attack']::text[], 'Forecasts the opponent''s next movement with 100% accuracy; a calculation-type skill like Predictive Calculation but specialised and far more accurate.', 'https://tensura.fandom.com/wiki/Future_Attack_Prediction', 'Wiki API fetch 2026-10-15 (skill pages)', false),
