  ('give_me_strength', 'Give Me Strength', 'Give Me Strength', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Magewolf Summon','Lend Me Power','Summon Demon Wolf']::text[], 'Summons Ranga; its evolved form of Fusion lets Gobta fully merge with Ranga.', 'https://tensura.fandom.com/wiki/Give_Me_Strength', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('glutton', 'Glutton', 'Glutton', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Gourmet','Gourmand']::text[], 'Sharper taste/smell and analysis of eaten food; Absolute Taste, Absolute Pressure', 'https://tensura.fandom.com/wiki/Glutton', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('gluttony', 'Gluttony', 'Gluttony', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Glutton','Gluttonous One','Overeater']::text[], 'Sub-skills: Predation, Stomach, Mimicry, Isolation, Corrosion, Provide, Receive', 'https://tensura.fandom.com/wiki/Gluttony', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('godwolf_sense', 'Godwolf Sense', 'Godwolf Sense', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Heavenly Wolf Awakening','Sense of Heavenly Wolf']::text[], 'Sensory-type Extra skill (ISEKAI Memories) used by Momiji, evolved from Mana Perception.', 'https://tensura.fandom.com/wiki/Godwolf_Sense', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('gourmand', 'Gourmand', 'Gourmand', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Fulfilled One','Instant Buddha']::text[], 'Strips a sufficiently weakened target of all its energy so the strength is gained permanently, even without killing.', 'https://tensura.fandom.com/wiki/Gourmand', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('gourmet', 'Gourmet', 'Gourmet', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Satiator']::text[], 'A gentler, refined Starved: lets Geld Junior share power and energy with subordinates safely, without madness or a feeding frenzy.', 'https://tensura.fandom.com/wiki/Gourmet', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('gravity_domination', 'Gravity Domination', 'Gravity Domination', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Dominate Gravity']::text[], 'Stronger Gravity Manipulation giving absolute control of gravity, including local supergravity to redirect attacks; very fast attacks can still get through.', 'https://tensura.fandom.com/wiki/Gravity_Domination', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('gravity_flight', 'Gravity Flight', 'Gravity Flight', 'common', 'Common skill / Intrinsic skill', ARRAY['Common']::text[], 'Main story', false, '{}'::text[], 'Floats in the air using natural gravity waves with no wings or magicules; boosts speed when combined with other flight methods.', 'https://tensura.fandom.com/wiki/Gravity_Flight', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('gravity_manipulation', 'Gravity Manipulation', 'Gravity Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Control Gravity']::text[], 'Manipulates and uses gravity, including floating like Gravity Flight and speeding flight when combined with other methods.', 'https://tensura.fandom.com/wiki/Gravity_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('great_sage', 'Great Sage', 'Great Sage', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Wise One','Sage']::text[], 'Analysis and support; speeds up skill learning', 'https://tensura.fandom.com/wiki/Great_Sage', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('greed', 'Greed', 'Greed', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Greedy One','Avarice']::text[], 'Evolved after defeat by Guy Crimson', 'https://tensura.fandom.com/wiki/Greed', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('grimoire', 'Grimoire', 'Grimoire', 'ultimate', 'Ultimate gift', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Book of Magic']::text[], 'Gives Gadra access to all of Ciel''s magic repertoire, shares Rimuru and Ciel''s magic knowledge, and can pass knowledge directly into another mind.', 'https://tensura.fandom.com/wiki/Grimoire', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('guardian', 'Guardian', 'Guardian', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Protector']::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Guardian', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('guide', 'Guide', 'Guide', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Game only', true, '{}'::text[], 'Draws power from the faith of the user''s believers.', 'https://tensura.fandom.com/wiki/Guide', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('haki', 'Haki', 'Haki', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Supreme Aura','Ambition','Presence']::text[], 'Exerts spiritual pressure that freezes targets and bends them to the user''s will, through aura or voice; only another Haki or great willpower overcomes it.', 'https://tensura.fandom.com/wiki/Haki', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('hamiel', 'Hamiel', 'Hamiel', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Splendour']::text[], 'Abilities currently unknown.', 'https://tensura.fandom.com/wiki/Hamiel', 'Wiki API fetch 2026-10-15 (skill pages)', false);
