  ('haniel', 'Haniel', 'Haniel', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Glory']::text[], 'Balance-centred: sees through traps, anticipates enemy movement, turns unfavourable attributes into advantageous ones and converts attack power.', 'https://tensura.fandom.com/wiki/Haniel', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('hastur', 'Hastur', 'Hastur', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Starwind','Lord of Stellar Winds']::text[], 'Transforms the user into a different form (details on the wiki page).', 'https://tensura.fandom.com/wiki/Hastur', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('healer', 'Healer', 'Healer', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Restorer','Medic']::text[], 'Manipulates viruses and air composition to spread viral poison, and can also heal, making the user very hard to kill by living creatures.', 'https://tensura.fandom.com/wiki/Healer', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('heat_source_perception', 'Heat Source Perception', 'Heat Source Perception', 'extra', 'Intrinsic skill / Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Sense Heat Source','Heat Sensing','Heat Perception']::text[], 'Detects heat reactions nearby, unaffected by ordinary concealment, though Haze can hide from it.', 'https://tensura.fandom.com/wiki/Heat_Source_Perception', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('heat_wave', 'Heat Wave', 'Heat Wave', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, '{}'::text[], 'Abilities currently unknown.', 'https://tensura.fandom.com/wiki/Heat_Wave', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('heavenly_eye', 'Heavenly Eye', 'Heavenly Eye', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Sky Eye','Heavengaze','Celestial Eye','Heaven''s Eye']::text[], 'Sees magicules, force and magic type before cast', 'https://tensura.fandom.com/wiki/Heavenly_Eye', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('hero_s_haki', 'Hero''s Haki', 'Hero''s Haki', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Hero''s Ambition','Heroic Presence','Heroic Aura','Bravery Aura','Heroes Haki']::text[], 'Haki that can also turn targets into allies instead of just bending them to the user''s will.', 'https://tensura.fandom.com/wiki/Hero''s_Haki', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('holy_haki', 'Holy Haki', 'Holy Haki', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Divine Haki','Sacred Haki']::text[], 'Hinata''s Extra skill under her Ultimate skill Fortuna.', 'https://tensura.fandom.com/wiki/Holy_Haki', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('holy_demonic_inversion', 'Holy-Demonic Inversion', 'Holy-Demonic Inversion', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Holy-Evil Inversion']::text[], 'Swaps between holy and demonic alignments to cover the weakness of each; can be applied to subordinates.', 'https://tensura.fandom.com/wiki/Holy-Demonic_Inversion', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('hydraulic_propulsion', 'Hydraulic Propulsion', 'Hydraulic Propulsion', 'common', 'Art / Common skill', ARRAY['Common']::text[], 'Main story', false, ARRAY['Water Pressure Proplusion']::text[], 'Uses pressure to fire a powerful water jet that carries the user long distances; Rimuru discovered it by swallowing water and expelling it.', 'https://tensura.fandom.com/wiki/Hydraulic_Propulsion', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('imitator', 'Imitator', 'Imitator', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Impersonator']::text[], 'Lets the user take the form of anyone seen, though full power of a much stronger target cannot be reproduced; judged more refined than Adapter.', 'https://tensura.fandom.com/wiki/Imitator', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('immortal', 'Immortal', 'Immortal', 'ultimate', 'Ultimate gift', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['The Deathless','Immortality']::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Immortal', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('immovable', 'Immovable', 'Immovable', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['All Things Immovability','All Things Unmoving','Impervious','Universal Immovability']::text[], 'Hardens the whole body tougher than most metals and keeps the user conscious and nearly unmovable, but not invincible.', 'https://tensura.fandom.com/wiki/Immovable', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('indra', 'Indra', 'Indra', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Thunderstorm','Lord of Thunder']::text[], 'Total control of lightning, the strongest natural power, and the ability to become lightning for divine-speed attacks.', 'https://tensura.fandom.com/wiki/Indra', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('infinite_regeneration', 'Infinite Regeneration', 'Infinite Regeneration', 'extra', 'Extra skill / Intrinsic skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Endless Regeneration']::text[], 'Heals any non-lethal damage incl. spirit/astral body/soul', 'https://tensura.fandom.com/wiki/Infinite_Regeneration', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('infinity_prison', 'Infinity Prison', 'Infinity Prison', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Endless Prison','Infinite Prison','Unlimited Imprisonment','Infinite Jail']::text[], 'Seals a target away', 'https://tensura.fandom.com/wiki/Infinity_Prison', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('intruder', 'Intruder', 'Intruder', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Game only', true, '{}'::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Intruder', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('investigator', 'Investigator', 'Investigator', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['I Want To Know','Inquirer']::text[], 'Accesses a record of the world''s events, reads surface thoughts and gives excellent information analysis.', 'https://tensura.fandom.com/wiki/Investigator', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('iron_wall', 'Iron Wall', 'Iron Wall', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, '{}'::text[], 'Greatly boosts defence and durability.', 'https://tensura.fandom.com/wiki/Iron_Wall', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('israfil', 'Israfil', 'Israfil', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Trials','Israfel']::text[], 'Spatial management comparable to a lower-tier Uriel: controls the flow of any matter or wavelength (down to Spiritrons) within its area.', 'https://tensura.fandom.com/wiki/Israfil', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('jibril', 'Jibril', 'Jibril', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Rigor']::text[], 'Makes the target''s body reproduce all the damage it has ever dealt to defeated opponents; only higher authority resists it.', 'https://tensura.fandom.com/wiki/Jibril', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('law_domination', 'Law Domination', 'Law Domination', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, '{}'::text[], 'Enhanced Law Manipulation allowing near-absolute control over world laws, still limited by the user''s understanding of the law.', 'https://tensura.fandom.com/wiki/Law_Domination', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('law_manipulation', 'Law Manipulation', 'Law Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Control Laws']::text[], 'Directly manipulates the laws of the world across all attributes to engineer almost any phenomenon; versatile but harder to use well.', 'https://tensura.fandom.com/wiki/Law_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('leader', 'Leader', 'Leader', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Game only', true, '{}'::text[], 'Effects unknown beyond being the combined evolution of Guide and Responder.', 'https://tensura.fandom.com/wiki/Leader', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('leviathan', 'Leviathan', 'Leviathan', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Envy']::text[], 'Degrades an opponent''s abilities; sub-skill Absorb', 'https://tensura.fandom.com/wiki/Leviathan', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('life_domination', 'Life Domination', 'Life Domination', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Dominate Life']::text[], 'Said to have authority over life and death; exact abilities vary by user but all concern the body and soul.', 'https://tensura.fandom.com/wiki/Life_Domination', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('life_drain', 'Life Drain', 'Life Drain', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, '{}'::text[], 'Takes energy (up to 10% of the user''s maximum Existence value) from a defeated target, adding part of the victim''s strength to the user''s.', 'https://tensura.fandom.com/wiki/Life_Drain', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('limiter', 'Limiter', 'Limiter', 'unique', 'Unique gift', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Determiner','Decider']::text[], 'Degraded Infinity Prison / Uriel''s Spatial Domination: creates a limiting space that only works on weaker opponents or consenting ones.', 'https://tensura.fandom.com/wiki/Limiter', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('looter', 'Looter', 'Looter', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Marauder','Plunderer']::text[], 'When the user kills a being, a dark copy with the same appearance, skills and power is created and can be summoned later; the number is limited.', 'https://tensura.fandom.com/wiki/Looter', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('lord_of_magewolves', 'Lord of Magewolves', 'Lord of Magewolves', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Demon Wolf King','King of Magewolves']::text[], 'Grants an extremely sensitive danger precognition.', 'https://tensura.fandom.com/wiki/Lord_of_Magewolves', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('lucifer', 'Lucifer', 'Lucifer', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Pride','Lord of Arrogance']::text[], 'Contains Beelzebuth, Leviathan, Satanael as sub-skills (Satanael usable up to 40%); pair: Uriel', 'https://tensura.fandom.com/wiki/Lucifer', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('lust', 'Lust', 'Lust', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, '{}'::text[], 'Appears in unique list', 'https://tensura.fandom.com/wiki/Lust', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('magic_aura', 'Magic Aura', 'Magic Aura', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Magic Fighting Spirit']::text[], 'Adds magical effects to the user''s aura using magicules, letting it harm spiritual life-forms and bypass magic resistance.', 'https://tensura.fandom.com/wiki/Magic_Aura', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('magic_flame_transformation', 'Magic Flame Transformation', 'Magic Flame Transformation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Demonic Flame Transformation','Magic Burn']::text[], 'Briefly turns the user into pure flame energy with the properties of a fully awakened spiritual life-form.', 'https://tensura.fandom.com/wiki/Magic_Flame_Transformation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('majesty', 'Majesty', 'Majesty', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, '{}'::text[], 'Abilities unconfirmed; possibly the source of Shuna''s power to command others with words, stronger than Bewilder.', 'https://tensura.fandom.com/wiki/Majesty', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('malice_perception', 'Malice Perception', 'Malice Perception', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Danger Detection','Danger Sense','Malice Sense','Sense Threat']::text[], 'Senses danger in the atmosphere and killing intent to spot incoming threats.', 'https://tensura.fandom.com/wiki/Malice_Perception', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('mammon', 'Mammon', 'Mammon', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Greed']::text[], 'Sub-skills: Absorb Life, Control Heart, Multilayer Barrier, Skill Steal, Thought Acceleration; art Lost Entropy', 'https://tensura.fandom.com/wiki/Mammon', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('mana_jamming', 'Mana Jamming', 'Mana Jamming', 'extra', 'Extra skill / Intrinsic skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Magic Jamming','Magic Interference','Magic Power Interference']::text[], 'Disturbs others'' mana and magicule flow, making the user resistant to magic; harpies use it to cancel others'' flight.', 'https://tensura.fandom.com/wiki/Mana_Jamming', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('mana_manipulation', 'Mana Manipulation', 'Mana Manipulation', 'extra', 'Extra skill / Intrinsic skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Control Magic','Magic Manipulation','Magic Power Manipulation']::text[], 'Finer control of mana to direct magicules and elements, and to disturb others'' mana.', 'https://tensura.fandom.com/wiki/Mana_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('mana_perception', 'Mana Perception', 'Mana Perception', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Magic Sense','Magic Perception','Magical Perception']::text[], 'Uses mana as an extra sense: 360-degree awareness of magicules with no blind spots, reading light and sound fluctuations.', 'https://tensura.fandom.com/wiki/Mana_Perception', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('manipulator', 'Manipulator', 'Manipulator', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Operator','Puppeteer','Marionettist']::text[], 'Converts information into encrypted data and sends it via electrical/magnetic forces in the ground for secure communication and wide-area surveillance.', 'https://tensura.fandom.com/wiki/Manipulator', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('manufacturer', 'Manufacturer', 'Manufacturer', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Creator','Maker','Producer']::text[], 'Lets the user create their own unique magic.', 'https://tensura.fandom.com/wiki/Manufacturer', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('martial_master', 'Martial Master', 'Martial Master', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Battle Lord','Martial Artist']::text[], 'Predicts the future within certain parameters (evolved from Heavenly Eye).', 'https://tensura.fandom.com/wiki/Martial_Master', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('mathematician', 'Mathematician', 'Mathematician', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Preserver','<s>Measurer</s>','Unchanging One']::text[], 'Sub-skills: Analytical Appraisal, Predictive Calculation, Thought Acceleration', 'https://tensura.fandom.com/wiki/Mathematician', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('megalomania', 'Megalomania', 'Megalomania', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Game only', true, ARRAY['Mirror of Delusion']::text[], 'Reads others'' subconscious through reflective surfaces and materialises their desires in the Mirror World; can pull people into it through reflections.', 'https://tensura.fandom.com/wiki/Megalomania', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('melchizedek', 'Melchizedek', 'Melchizedek', 'ultimate', 'Ultimate skill / Ultimate enchantment', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Dominion','Lord of Domination']::text[], 'Listed under Enchantment', 'https://tensura.fandom.com/wiki/Melchizedek', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('mental_crush', 'Mental Crush', 'Mental Crush', 'extra', 'Extra skill / Illusion magic', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Spiritual Destruction','Mental Strike']::text[], 'Extra skill (illusion magic from the Grimoire/Necronomicon) used by Adalmann, Diablo, Gadra, Razen and Rimuru to damage minds.', 'https://tensura.fandom.com/wiki/Mental_Crush', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('mephisto', 'Mephisto', 'Mephisto', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Fantasy','Lord of Illusion']::text[], 'Creates a world where everything follows Zegion''s wishes, even bending the flow of time.', 'https://tensura.fandom.com/wiki/Mephisto', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('merciless', 'Merciless', 'Merciless', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Heartless','Heartless One','Merciless One']::text[], 'Appears in unique list', 'https://tensura.fandom.com/wiki/Merciless', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('metal_manipulation', 'Metal Manipulation', 'Metal Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Control Metal']::text[], 'Manipulates any metal, even god-grade ones such as the Azure Dragon Spear.', 'https://tensura.fandom.com/wiki/Metal_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false);
insert into slime_skills (id, name, wiki_title, tier_group, tier_wiki, wiki_categories, scope, noncanon_page, aliases, effect, wiki_url, source, in_unique_pool) values
  ('metatron', 'Metatron', 'Metatron', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Purity','Lord of Chastity']::text[], 'Pair: Asmodeus', 'https://tensura.fandom.com/wiki/Metatron', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('metis', 'Metis', 'Metis', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Retribution','Lord of Sanction']::text[], 'Combat-focused, surpassing even Uriel: manipulates all matter and wavelengths down to Spiritrons in a targeted space.', 'https://tensura.fandom.com/wiki/Metis', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('michael_skill', 'Michael (skill)', 'Michael (skill)', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Justice','Mikael']::text[], 'Authority over free will: control others, steal skills; can copy other Ultimates; pair: Satanael', 'https://tensura.fandom.com/wiki/Michael_(skill)', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('milim_ear', 'Milim Ear', 'Milim Ear', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, '{}'::text[], 'Greatly sharpens hearing and lets the user overhear almost any communication; only discreet soul-corridor channels escape it.', 'https://tensura.fandom.com/wiki/Milim_Ear', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('milim_eye', 'Milim Eye', 'Milim Eye', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Dragon''s Eye']::text[], 'Greatly improves eyesight and sees through anything including lies, making the user hard to deceive, though they may miss things they do not want to see.', 'https://tensura.fandom.com/wiki/Milim_Eye', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('molecular_manipulation', 'Molecular Manipulation', 'Molecular Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Control Particles']::text[], 'Controls the paths of molecules in the air to use elements by manipulating environmental magicules; friction can create heat.', 'https://tensura.fandom.com/wiki/Molecular_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('mood_maker', 'Mood Maker', 'Mood Maker', 'ultimate', 'Ultimate gift', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Psychology']::text[], 'Rewrites an event''s result in favour of the user or allies; once a day per target, and can be activated at will in the newer version.', 'https://tensura.fandom.com/wiki/Mood_Maker', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('mortal_fear', 'Mortal Fear', 'Mortal Fear', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Fearful Haki']::text[], 'Uses haki to incite fear so enemies lose their will to fight and cannot use full strength.', 'https://tensura.fandom.com/wiki/Mortal_Fear', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('motherly_queen', 'Motherly Queen', 'Motherly Queen', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Queen Worship']::text[], 'Absorbs the ecology of eaten insects and brings it into the world as majin.', 'https://tensura.fandom.com/wiki/Motherly_Queen', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('multidimensional_barrier', 'Multidimensional Barrier', 'Multidimensional Barrier', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Multi-Dimensional Barrier']::text[], 'Absolute-defence barrier: an always-on Multilayer Barrier plus Dimension Fault (upgraded Distortion Field), foolproof against physical, elemental and emission attacks.', 'https://tensura.fandom.com/wiki/Multidimensional_Barrier', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('multilayer_barrier', 'Multilayer Barrier', 'Multilayer Barrier', 'extra', 'Extra skill / Intrinsic skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Multiple Barrier']::text[], 'A thin invisible coat of linked Ranged Barriers with different resistances, barely visible even to Mana Perception.', 'https://tensura.fandom.com/wiki/Multilayer_Barrier', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('multiple_weapons', 'Multiple Weapons', 'Multiple Weapons', 'ultimate', 'Ultimate enchantment', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Martial Creation','Multi-Weapon']::text[], 'Materialises god-grade equipment for the user and others in any form, with a cap on how much can exist at once; created gear vanishes afterwards.', 'https://tensura.fandom.com/wiki/Multiple_Weapons', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('murderer', 'Murderer', 'Murderer', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Assassin']::text[], 'Stealth and assassination: near-total concealment like Haze and erased sound from the user.', 'https://tensura.fandom.com/wiki/Murderer', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('musician', 'Musician', 'Musician', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Performer']::text[], 'Controls sound waves: sonic attacks, tracking allies and enemies, and special sound-wave messages.', 'https://tensura.fandom.com/wiki/Musician', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('necronomicon', 'Necronomicon', 'Necronomicon', 'ultimate', 'Ultimate gift', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Book of Magic']::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Necronomicon', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('nodens', 'Nodens', 'Nodens', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['God of Abyss']::text[], 'Like Lucifer, allows complete reproduction of any ability the user has seen once.', 'https://tensura.fandom.com/wiki/Nodens', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('nyarlathotep', 'Nyarlathotep', 'Nyarlathotep', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Chaos']::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Nyarlathotep', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('observer', 'Observer', 'Observer', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Discerner']::text[], 'Keeps contact with anyone across space and time, but only with people the user already knows.', 'https://tensura.fandom.com/wiki/Observer', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('observing_eye', 'Observing Eye', 'Observing Eye', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Observation Eye','Eye of Observation']::text[], 'Greatly improves vision, even seeing magicules and spiritual matter; with Mana Perception it reveals faint traces of magic.', 'https://tensura.fandom.com/wiki/Observing_Eye', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('oppressor', 'Oppressor', 'Oppressor', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, '{}'::text[], 'Exerts force from psychological pressure to physical compression within line of sight, like a star''s gravity that can be directed.', 'https://tensura.fandom.com/wiki/Oppressor', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('optimist', 'Optimist', 'Optimist', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Ignorant One']::text[], 'Multiplies the user''s power several times, but only when acting on orders.', 'https://tensura.fandom.com/wiki/Optimist', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('orpheus', 'Orpheus', 'Orpheus', 'ultimate', 'Ultimate enchantment', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Optimistic Performer']::text[], 'Keeps Optimist and Manipulator with Optimist''s restriction removed, combining rapid strength gain with perfect control of movement.', 'https://tensura.fandom.com/wiki/Orpheus', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('overcomer', 'Overcomer', 'Overcomer', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Game only', true, ARRAY['Survivor']::text[], 'Raises the user''s power the closer they are to death.', 'https://tensura.fandom.com/wiki/Overcomer', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('parallel_calculation', 'Parallel Calculation', 'Parallel Calculation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Parallel Computation','Parallel Operation','Parallel Processing','Parallelism']::text[], 'Run calculations apart from normal thought', 'https://tensura.fandom.com/wiki/Parallel_Calculation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('parallel_existence', 'Parallel Existence', 'Parallel Existence', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, '{}'::text[], 'Splits consciousness into identical, fully autonomous beings with their own souls (unlike Body Double).', 'https://tensura.fandom.com/wiki/Parallel_Existence', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('parallel_thought', 'Parallel Thought', 'Parallel Thought', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Parallel Thinking']::text[], 'Splits the mind into sub-units that think independently, like Parallel Calculation but with a different principle.', 'https://tensura.fandom.com/wiki/Parallel_Thought', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('paralyzing_breath', 'Paralyzing Breath', 'Paralyzing Breath', 'common', 'Intrinsic skill / Common skill', ARRAY['Common']::text[], 'Main story', false, ARRAY['Paralysis Breath']::text[], 'Breathes gas up to ten metres that paralyses targets for a long time.', 'https://tensura.fandom.com/wiki/Paralyzing_Breath', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('paranoia', 'Paranoia', 'Paranoia', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Game only', true, ARRAY['Mirror of Revision']::text[], 'Lets beings created in the Mirror World appear in the outside world or be pulled back in.', 'https://tensura.fandom.com/wiki/Paranoia', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('perceiver', 'Perceiver', 'Perceiver', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Observer']::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Perceiver', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('perfect_memory', 'Perfect Memory', 'Perfect Memory', 'extra', 'Intrinsic skill / Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Complete Memory']::text[], 'Records memories into the astral body (normally spirit-only), granting immunity to mind control outside it and long memory retention.', 'https://tensura.fandom.com/wiki/Perfect_Memory', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('planner', 'Planner', 'Planner', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Schemer']::text[], 'Devises plans suited to the circumstances so the user always profits.', 'https://tensura.fandom.com/wiki/Planner', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('poison_breath', 'Poison Breath', 'Poison Breath', 'common', 'Intrinsic skill / Common skill', ARRAY['Common']::text[], 'Main story', false, ARRAY['Poisonous Breath']::text[], 'Spews highly poisonous gas up to ten metres in a 120-degree arc that corrodes what it touches.', 'https://tensura.fandom.com/wiki/Poison_Breath', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('poison_paralysis_corrosion_conferment', 'Poison-Paralysis-Corrosion Conferment', 'Poison-Paralysis-Corrosion Conferment', 'common', 'Common skill', ARRAY['Common']::text[], 'Main story', false, ARRAY['Apply Poison/Paralysis/Rot']::text[], 'Applies poison, paralysis and/or corrosion to anything touched or hit by the user''s attacks.', 'https://tensura.fandom.com/wiki/Poison-Paralysis-Corrosion_Conferment', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('predator', 'Predator', 'Predator', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Devourer']::text[], 'Consume targets to gain skills and resistances', 'https://tensura.fandom.com/wiki/Predator', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('predictive_calculation', 'Predictive Calculation', 'Predictive Calculation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Compute Prediction']::text[], 'Calculates and predicts outcomes of actions or events, including reading the user''s flow of power to avoid waste.', 'https://tensura.fandom.com/wiki/Predictive_Calculation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('presence_detection', 'Presence Detection', 'Presence Detection', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Detect Aura']::text[], 'A detection skill; other abilities unknown.', 'https://tensura.fandom.com/wiki/Presence_Detection', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('pride', 'Pride', 'Pride', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, '{}'::text[], 'Combined with Guy''s calculation ability, lets him imitate abilities he has seen.', 'https://tensura.fandom.com/wiki/Pride', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('proserpina', 'Proserpina', 'Proserpina', 'ultimate', 'Ultimate gift', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Queen Worship','Proserpine']::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Proserpina', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('quantum_manipulation', 'Quantum Manipulation', 'Quantum Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Quantum Control']::text[], 'Abilities unknown.', 'https://tensura.fandom.com/wiki/Quantum_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('raguel', 'Raguel', 'Raguel', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Charity','Lord of Relief']::text[], 'Destructive energy; pair: Mammon', 'https://tensura.fandom.com/wiki/Raguel', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('ranged_barrier', 'Ranged Barrier', 'Ranged Barrier', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Area Boundary']::text[], 'Instantly creates a barrier up to 100 m around the user, trapping opponents; its power does not change with size.', 'https://tensura.fandom.com/wiki/Ranged_Barrier', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('raphael', 'Raphael', 'Raphael', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Wisdom','Lord of Knowledge','Rafael','Lord of Fortitude']::text[], 'Manages world laws, support, skill alteration', 'https://tensura.fandom.com/wiki/Raphael', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('reaper', 'Reaper', 'Reaper', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Collector','Gatherer','Harvester']::text[], 'Splits off body parts as clones of varying sizes that stay linked to the user''s consciousness, letting them act in several places.', 'https://tensura.fandom.com/wiki/Reaper', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('recorder', 'Recorder', 'Recorder', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, '{}'::text[], 'Nature and abilities unknown.', 'https://tensura.fandom.com/wiki/Recorder', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('reflector', 'Reflector', 'Reflector', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Double Winner','Duplicator']::text[], 'Stores any attack that landed on the user and reflects it back; the cost is that the user must take the damage first.', 'https://tensura.fandom.com/wiki/Reflector', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('regressor', 'Regressor', 'Regressor', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Redoer','Returner','Survivor']::text[], 'When the user dies, they are sent back to a fixed earlier point with their memories, creating a time loop.', 'https://tensura.fandom.com/wiki/Regressor', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('researcher', 'Researcher', 'Researcher', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, '{}'::text[], 'Sub-skills: Omni Analysis, Spatial Storage, Transmutation', 'https://tensura.fandom.com/wiki/Researcher', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('responder', 'Responder', 'Responder', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Game only', true, '{}'::text[], 'Makes a target unconditionally believe the user''s words when the target has no answer of their own.', 'https://tensura.fandom.com/wiki/Responder', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('reverser', 'Reverser', 'Reverser', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Double-Crosser','Heavenly Demon','Heavenly Evil Oni','Inside-Out']::text[], 'Creates and fuses opposing natures into a new contradictory form; Beretta used it to fuse angelic essence, becoming something beyond angel or daemon.', 'https://tensura.fandom.com/wiki/Reverser', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('rex', 'Rex', 'Rex', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Game only', true, ARRAY['Lord of Mirror Dragons','Mirror Dragon King']::text[], 'Game-only (ISEKAI Memories). Recreates objects the user made before, converts mirror-world magicules and passes the user''s abilities and the Mirror World to a target.', 'https://tensura.fandom.com/wiki/Rex', 'Wiki API fetch 2026-10-15 (skill pages)', false);
insert into slime_skills (id, name, wiki_title, tier_group, tier_wiki, wiki_categories, scope, noncanon_page, aliases, effect, wiki_url, source, in_unique_pool) values
  ('royal_beast_form', 'Royal Beast Form', 'Royal Beast Form', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Royal Beast Transformation']::text[], 'Chimera-like transformation, triple strength, then weakened', 'https://tensura.fandom.com/wiki/Royal_Beast_Form', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('sage', 'Sage', 'Sage', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, '{}'::text[], 'Accelerates the user''s thought process.', 'https://tensura.fandom.com/wiki/Sage', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('samael', 'Samael', 'Samael', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Deathly Poison','Lord of Poison','Lord of Deadly Venom','Lord of Deadly Toxins']::text[], 'Finds a target''s weaknesses and helps make a poison tailored to kill them; refines it to the target''s lethal dose and kills nearly anything except spiritual life-forms.', 'https://tensura.fandom.com/wiki/Samael', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('sandalphon', 'Sandalphon', 'Sandalphon', 'ultimate', 'Ultimate skill / Ultimate enchantment', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Judgment','Lord of Punishment','Lord of Condemnation','Lord of Conviction','Lord of Damnation']::text[], 'Wiki navbox files it under Enchantment', 'https://tensura.fandom.com/wiki/Sandalphon', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('sariel', 'Sariel', 'Sariel', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Hope']::text[], 'Authority over life and the reincarnation cycle; pair: Belphegor', 'https://tensura.fandom.com/wiki/Sariel', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('satanael', 'Satanael', 'Satanael', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Wrath']::text[], 'Sub-skills: Magicule Breeder Reactor, Stampede; pair: Michael', 'https://tensura.fandom.com/wiki/Satanael', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('scale_armor', 'Scale Armor', 'Scale Armor', 'common', 'Common skill / Intrinsic skill', ARRAY['Common']::text[], 'Main story', false, ARRAY['Webbed Feet']::text[], 'Gives the user reptile-like scales as armor and likely reshapes limbs (orcs that ate a lizardman grew webbed limbs for walking on water).', 'https://tensura.fandom.com/wiki/Scale_Armor', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('scavenger', 'Scavenger', 'Scavenger', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Evil Eater']::text[], 'Gains the properties of any prey eaten, even god-grade equipment.', 'https://tensura.fandom.com/wiki/Scavenger', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('seeker', 'Seeker', 'Seeker', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Great Wiseman','Pursuer','Wise Man']::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Seeker', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('seer', 'Seer', 'Seer', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Future Vision','Future Sight']::text[], 'Perfect precognition a few seconds ahead so the user is never caught off guard; especially strong with Falsifier.', 'https://tensura.fandom.com/wiki/Seer', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('self_regeneration', 'Self-Regeneration', 'Self-Regeneration', 'extra', 'Extra skill{{Ref|LN|vol = 6|ch = 3}}{{Ref|LN|vol = 7|ch = 4}}{{Ref|LN|vol = 9|ch = 3}} / Intrinsic skill / Common skill{{Ref|LN|vol = 2|ch = Status}}{{Ref|LN|vol = 5|ch = Status}}', ARRAY['Extra','Common']::text[], 'Main story', false, ARRAY['Regeneration','Automatic Regeneration']::text[], 'Heals nearly any injury over time at an energy cost, including lost limbs and organs, as long as the user has magicules and an intact-enough body.', 'https://tensura.fandom.com/wiki/Self-Regeneration', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('sentient_being', 'Sentient Being', 'Sentient Being', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Game only', true, '{}'::text[], 'Strengthens whoever the user wants as family and connects their magicules (it let Izis use Veldora Against''s magicules).', 'https://tensura.fandom.com/wiki/Sentient_Being', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('sephirot', 'Sephirot', 'Sephirot', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Life','Sefirot']::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Sephirot', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('severer', 'Severer', 'Severer', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Amputator','Mutilator']::text[], 'Makes swords with the Space element and swaps a real sword for a dummy at will; dummies look identical but are space-distorting constructs.', 'https://tensura.fandom.com/wiki/Severer', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('shadow_motion', 'Shadow Motion', 'Shadow Motion', 'extra', 'Extra skill / Intrinsic skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Shadow Movement','Shadow Step']::text[], 'Opens a shadow space linking all shadows with no air and no heat dissipation, shortening travel distance.', 'https://tensura.fandom.com/wiki/Shadow_Motion', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('shadow_striker', 'Shadow Striker', 'Shadow Striker', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Ninja']::text[], 'Damages spiritual bodies, bypassing physical defence and hurting spiritual life-forms that are immune to physical damage.', 'https://tensura.fandom.com/wiki/Shadow_Striker', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('shub_niggurath', 'Shub-Niggurath', 'Shub-Niggurath', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Harvest','Lord of Abundance','Lord of Fertility']::text[], 'Based on the bond between Rimuru and subordinates: lets Rimuru grant energy, information or skills through soul corridors.', 'https://tensura.fandom.com/wiki/Shub-Niggurath', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('shub_niggurath_skill_storage', 'Shub-Niggurath/Skill Storage', 'Shub-Niggurath/Skill Storage', 'ultimate', NULL, ARRAY['Ultimate']::text[], NULL, false, '{}'::text[], 'Sub-page of Shub-Niggurath (no infobox or ability text).', 'https://tensura.fandom.com/wiki/Shub-Niggurath/Skill_Storage', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('sloth', 'Sloth', 'Sloth', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, '{}'::text[], 'Accumulates energy: the lazier the user, the stronger they get.', 'https://tensura.fandom.com/wiki/Sloth', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('small_world', 'Small World', 'Small World', 'ultimate', 'Intrinsic skill / Ultimate skill{{Ref|LN|vol = 18|ch = 1}}', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Labyrinth Creation','Tiny World','Mazecraft','Maze Creation']::text[], 'Creates a near-endless labyrinth of isolated space with chosen shapes; can isolate dimensions and is hard to break from outside.', 'https://tensura.fandom.com/wiki/Small_World', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('snake_eye', 'Snake Eye', 'Snake Eye', 'extra', NULL, ARRAY['Extra']::text[], NULL, false, '{}'::text[], 'Inflicts status ailments on anyone in sight, including their gear; potency depends on the user''s strength relative to the target.', 'https://tensura.fandom.com/wiki/Snake_Eye', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('sniper', 'Sniper', 'Sniper', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, '{}'::text[], 'Coordinate calculation and spatial manipulation so projectiles always hit; as a soul-rooted skill it gave Glenda some protection against mental effects.', 'https://tensura.fandom.com/wiki/Sniper', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('sound_wave_perception', 'Sound Wave Perception', 'Sound Wave Perception', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Sense Soundwave']::text[], 'Detects sound waves precisely and infers the movement and location of creatures from them.', 'https://tensura.fandom.com/wiki/Sound_Wave_Perception', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('spacetime_domination', 'Spacetime Domination', 'Spacetime Domination', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Dominate Dimensions']::text[], 'Stronger Spacetime Manipulation: complete space control plus ability to affect time; makes Spacetime Connection and Instant Motion easy.', 'https://tensura.fandom.com/wiki/Spacetime_Domination', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('spacetime_manipulation', 'Spacetime Manipulation', 'Spacetime Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Control Dimensions']::text[], 'Stronger Spatial Domination: complete space control and minimal time control; enables Spacetime Connection or Instant Motion.', 'https://tensura.fandom.com/wiki/Spacetime_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('spatial_domination', 'Spatial Domination', 'Spatial Domination', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Dominate Space','Control Space']::text[], 'Stronger Spatial Manipulation: complete control of the Space element, easy teleportation and wide-area blocking or restriction.', 'https://tensura.fandom.com/wiki/Spatial_Domination', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('spatial_manipulation', 'Spatial Manipulation', 'Spatial Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Space Manipulation','Control Space']::text[], 'Controls and interferes with nearby space, from basic portal teleportation to more advanced uses depending on proficiency.', 'https://tensura.fandom.com/wiki/Spatial_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('spatial_motion', 'Spatial Motion', 'Spatial Motion', 'extra', 'Extra skill / Intrinsic skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Spatial Movement','Spatial Travel','Teleportation','Spatial Transition','Spatial Transport']::text[], 'Instant travel to any known place or coordinate by linking two points with a stabilised gate.', 'https://tensura.fandom.com/wiki/Spatial_Motion', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('spatial_storage', 'Spatial Storage', 'Spatial Storage', 'extra', 'Spatial magic / Extra skill', ARRAY['Extra']::text[], 'Main story', false, '{}'::text[], 'Stores items in a personal subspace, similar to Stomach; the spell version has majin and human variants.', 'https://tensura.fandom.com/wiki/Spatial_Storage', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('spearhead', 'Spearhead', 'Spearhead', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Commander','Leader']::text[], 'Leads subordinates in battle like Commander: understands the power of those led and uses it well.', 'https://tensura.fandom.com/wiki/Spearhead', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('spiral_body', 'Spiral Body', 'Spiral Body', 'unique', 'Intrinsic skill / Unique skill', ARRAY['Unique']::text[], 'Game only', true, ARRAY['Helix']::text[], 'Adds the piercing attribute to the whole body.', 'https://tensura.fandom.com/wiki/Spiral_Body', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('spiritual_domination', 'Spiritual Domination', 'Spiritual Domination', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Mental Domination','Spirit Domination']::text[], 'Complete control over a target''s thoughts and emotions.', 'https://tensura.fandom.com/wiki/Spiritual_Domination', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('spiritual_manipulation', 'Spiritual Manipulation', 'Spiritual Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Mental Manipulation','Spiritual Control','Spirit Control']::text[], 'Partial control over a target''s thoughts and emotions.', 'https://tensura.fandom.com/wiki/Spiritual_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('starved', 'Starved', 'Starved', 'unique', 'Intrinsic skill / Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Ravenous','Starving Ones']::text[], 'Share hunger/gains with subordinates; Rimuru absorbed it and merged it with Predator', 'https://tensura.fandom.com/wiki/Starved', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('steel_strength', 'Steel Strength', 'Steel Strength', 'extra', 'Extra skill / Intrinsic skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Herculean Strength','Superhuman Strength']::text[], 'Greatly boosts physical strength.', 'https://tensura.fandom.com/wiki/Steel_Strength', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('steel_thread', 'Steel Thread', 'Steel Thread', 'common', 'Intrinsic skill / Common skill', ARRAY['Common']::text[], 'Main story', false, '{}'::text[], 'Creates very durable, hard-to-see threads for blocking attacks or cutting enemies, strong enough to cut trees.', 'https://tensura.fandom.com/wiki/Steel_Thread', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('sticky_thread', 'Sticky Thread', 'Sticky Thread', 'common', 'Intrinsic skill / Common skill', ARRAY['Common']::text[], 'Main story', false, '{}'::text[], 'Creates sticky threads that immobilise an opponent, controllable with Telepathy.', 'https://tensura.fandom.com/wiki/Sticky_Thread', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('sticky_steel_thread', 'Sticky-Steel Thread', 'Sticky-Steel Thread', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, '{}'::text[], 'Combines Sticky and Steel Thread: tougher, takes the user''s resistances, can carry Thought Communication and is suited to capturing stronger foes.', 'https://tensura.fandom.com/wiki/Sticky-Steel_Thread', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('strengthen', 'Strengthen', 'Strengthen', 'common', 'Common skill / Intrinsic skill', ARRAY['Common']::text[], 'Main story', false, '{}'::text[], 'Strengthens the user''s body.', 'https://tensura.fandom.com/wiki/Strengthen', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('strengthen_body', 'Strengthen Body', 'Strengthen Body', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Physical Enhancement']::text[], 'Boosts muscle strength.', 'https://tensura.fandom.com/wiki/Strengthen_Body', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('supporter', 'Supporter', 'Supporter', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Game only', true, '{}'::text[], 'Increases the power of the user''s allies.', 'https://tensura.fandom.com/wiki/Supporter', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('suppressor', 'Suppressor', 'Suppressor', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Oppressor']::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Suppressor', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('survivor', 'Survivor', 'Survivor', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, '{}'::text[], 'Strong defence: regenerates from all wounds and grants immunity to many natural effects and elements; with Berserker the user becomes nearly unstoppable.', 'https://tensura.fandom.com/wiki/Survivor', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('surya', 'Surya', 'Surya', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Brilliance','Lord of Light','Lord of Shine','Lord of Glitter']::text[], 'Adds to Metatron''s purification of energy with complete control of Spiritrons, removing collateral damage so Leon can go all out.', 'https://tensura.fandom.com/wiki/Surya', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('susanoo', 'Susanoo', 'Susanoo', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Tyranny','King of Atrocity','King of Violence','Lord of Violence','Susano-oh']::text[], 'Counters received energy with the user''s own, neutralising and converting it, and can steal the target''s energy for the user''s attacks.', 'https://tensura.fandom.com/wiki/Susanoo', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('telepathy', 'Telepathy', 'Telepathy', 'common', 'Common skill', ARRAY['Common']::text[], 'Main story', false, ARRAY['Telepathic Communication']::text[], 'Two people talk by thought through magicule exchange.', 'https://tensura.fandom.com/wiki/Telepathy', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('temporal_manipulation', 'Temporal Manipulation', 'Temporal Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Control Time','Time Manipulation']::text[], 'Manipulates and uses the Time element.', 'https://tensura.fandom.com/wiki/Temporal_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('tempter', 'Tempter', 'Tempter', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Enchanter','Seducer']::text[], 'Seizes the soul of anyone whose will the user has broken; rebellious acts are reported to the user and the soul is taken even if the victim dies another way. Rules through fear.', 'https://tensura.fandom.com/wiki/Tempter', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('terra_mater', 'Terra Mater', 'Terra Mater', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Cosmos']::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Terra_Mater', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('thought_acceleration', 'Thought Acceleration', 'Thought Acceleration', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Hasten Thought','Mind Accelerate']::text[], '~1,000,000x faster thought', 'https://tensura.fandom.com/wiki/Thought_Acceleration', 'Wiki API fetch 2026-10-15 (skill pages)', false);
insert into slime_skills (id, name, wiki_title, tier_group, tier_wiki, wiki_categories, scope, noncanon_page, aliases, effect, wiki_url, source, in_unique_pool) values
  ('thought_communication', 'Thought Communication', 'Thought Communication', 'common', 'Common skill / Intrinsic skill', ARRAY['Common']::text[], 'Main story', false, ARRAY['Thought Transmission','Telepathy Net']::text[], 'Telepathic talk with several people at once, far stronger than Telepathy (two people); range depends on the user and can be extended by skills such as Sticky-Steel Thread.', 'https://tensura.fandom.com/wiki/Thought_Communication', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('thought_domination', 'Thought Domination', 'Thought Domination', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Dominate Thought']::text[], 'Controls others'' thoughts and makes them follow orders, from subtle influence to full control; also usable as telepathy.', 'https://tensura.fandom.com/wiki/Thought_Domination', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('thought_manipulation', 'Thought Manipulation', 'Thought Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Control Thought']::text[], 'Manipulates others'' thoughts to influence their actions.', 'https://tensura.fandom.com/wiki/Thought_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('thrower', 'Thrower', 'Thrower', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Hurler','Tosser']::text[], 'Lets the user throw anything they can grip, even a monster or air, with strong impact.', 'https://tensura.fandom.com/wiki/Thrower', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('time_traveler', 'Time Traveler', 'Time Traveler', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, '{}'::text[], 'Sends the user back in time once a very specific set of conditions is met. One-way, triggers automatically, and heavily restricted.', 'https://tensura.fandom.com/wiki/Time_Traveler', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('tough_guy', 'Tough Guy', 'Tough Guy', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, '{}'::text[], 'Same core as Immovable but pushed to the extreme.', 'https://tensura.fandom.com/wiki/Tough_Guy', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('traveler', 'Traveler', 'Traveler', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Drifter']::text[], 'Effects not known on the wiki.', 'https://tensura.fandom.com/wiki/Traveler', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('true_hero', 'True Hero', 'True Hero', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Heroes','King of Heroes']::text[], 'A balance-breaker that turns the tide of any battle just by being active, far beyond Chosen One; can call fallen allies and copy their abilities and experience, and guides allies toward becoming heroes.', 'https://tensura.fandom.com/wiki/True_Hero', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('tsukuyomi', 'Tsukuyomi', 'Tsukuyomi', 'ultimate', 'Ultimate gift', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Moonshade','Lord of Shadow Moon','Lord of Moonlight']::text[], 'No ability text on the wiki page.', 'https://tensura.fandom.com/wiki/Tsukuyomi', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('tuner', 'Tuner', 'Tuner', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Braggart','Lucky Devil']::text[], 'Raises attack power only through unintended action, scaling with the user''s mood; a second effect can alter fate to avoid certain death, once per day and not on demand.', 'https://tensura.fandom.com/wiki/Tuner', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('tyrant', 'Tyrant', 'Tyrant', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Dictator','The Top']::text[], 'Lets the user see through everything including thoughts; mastery lets them enrich their energy and fold it into attacks.', 'https://tensura.fandom.com/wiki/Tyrant', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('ultra_acceleration', 'Ultra Acceleration', 'Ultra Acceleration', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Super Acceleration','Ultraspeed']::text[], 'Dramatically increases momentum of the user''s movements or projectile attacks.', 'https://tensura.fandom.com/wiki/Ultra_Acceleration', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('ultra_intuition', 'Ultra Intuition', 'Ultra Intuition', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Hyper-Intuition']::text[], 'Senses abstract things normally imperceptible, such as the overall strength of a force or an entity''s nature.', 'https://tensura.fandom.com/wiki/Ultra_Intuition', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('ultra_recovery', 'Ultra Recovery', 'Ultra Recovery', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Super Recovery']::text[], 'Once a day, nullifies all damage by switching between human and dragon form.', 'https://tensura.fandom.com/wiki/Ultra_Recovery', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('ultra_sense', 'Ultra Sense', 'Ultra Sense', 'extra', 'Extra skill / Intrinsic skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Ultra Intuition']::text[], 'Detects and discerns surroundings with near-absolute accuracy and locates members of the user''s soul lineage at any distance.', 'https://tensura.fandom.com/wiki/Ultra_Sense', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('ultra_smell', 'Ultra Smell', 'Ultra Smell', 'extra', 'Extra skill / Intrinsic skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Keen Smell','Supreme Sense of Smell']::text[], 'Greatly improved sense of smell for detecting, identifying and tracking by scent.', 'https://tensura.fandom.com/wiki/Ultra_Smell', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('ultra_sound_waves', 'Ultra Sound Waves', 'Ultra Sound Waves', 'extra', 'Intrinsic skill / Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Hyper Soundwaves','Ultrasonic Waves']::text[], 'Emits ultrasonic waves; at higher intensity can confuse or knock out targets.', 'https://tensura.fandom.com/wiki/Ultra_Sound_Waves', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('ultra_vibration', 'Ultra Vibration', 'Ultra Vibration', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Super Vibration','Hyper Vibration']::text[], 'Precise effects unknown; presumably creates and controls large-scale vibrations, derived from Ultra Sound Waves.', 'https://tensura.fandom.com/wiki/Ultra_Vibration', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('ultraspeed_action', 'Ultraspeed Action', 'Ultraspeed Action', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Ultraspeed','Super Speed Action','Overdrive']::text[], 'Evolution of Ultra Acceleration; not elaborated, presumably greatly increases momentum of people and objects.', 'https://tensura.fandom.com/wiki/Ultraspeed_Action', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('ultraspeed_reaction', 'Ultraspeed Reaction', 'Ultraspeed Reaction', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Ultra Reactions']::text[], 'Not elaborated; apparently greatly improves reaction time (humans could fight supersonic army wasps).', 'https://tensura.fandom.com/wiki/Ultraspeed_Reaction', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('ultraspeed_regeneration', 'Ultraspeed Regeneration', 'Ultraspeed Regeneration', 'extra', 'Extra skill / Intrinsic skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Rapid Regeneration','Super-Fast Regeneration','Super-Regeneration']::text[], 'Fast material-body regeneration; can be disabled by spiritrons', 'https://tensura.fandom.com/wiki/Ultraspeed_Regeneration', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('ultraspeed_thought', 'Ultraspeed Thought', 'Ultraspeed Thought', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Super-Speed Thinking','Thought Hyper-Acceleration']::text[], 'Accelerates thought by a factor of potentially over a million, like Thought Acceleration.', 'https://tensura.fandom.com/wiki/Ultraspeed_Thought', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('universal_perception', 'Universal Perception', 'Universal Perception', 'extra', 'Intrinsic skill / Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Universal Detect','Universal Sense']::text[], 'Enhanced Mana Perception covering nearly everything in a very wide radius, beyond light and sound.', 'https://tensura.fandom.com/wiki/Universal_Perception', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('universal_shapeshift', 'Universal Shapeshift', 'Universal Shapeshift', 'extra', 'Extra skill / Intrinsic skill', ARRAY['Extra']::text[], 'Main story', false, '{}'::text[], 'Freely changes bodily properties and appearance with little effort, using small mana or absorbed matter to reform.', 'https://tensura.fandom.com/wiki/Universal_Shapeshift', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('unyielding', 'Unyielding', 'Unyielding', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Indomitable','Nefarious','Tenacious','Hopeful']::text[], 'Evolved into Sariel after the souls of Maria, Razul and Granbell resonated', 'https://tensura.fandom.com/wiki/Unyielding', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('uriel', 'Uriel', 'Uriel', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Vows','Lord of Faith','Lord of Covenants','Lord of Oath']::text[], 'Defence and spatial control; pair: Lucifer', 'https://tensura.fandom.com/wiki/Uriel', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('usurper', 'Usurper', 'Usurper', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Robber','Surpasser']::text[], 'Appears in unique category listing', 'https://tensura.fandom.com/wiki/Usurper', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('vayu', 'Vayu', 'Vayu', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Heavenly Wind','Lord of Wind']::text[], 'Specialises in speed and manipulating the atmosphere, including making footholds in the sky.', 'https://tensura.fandom.com/wiki/Vayu', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('veldora_skill', 'Veldora (skill)', 'Veldora (skill)', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Storms','Gulli-dora']::text[], 'Game-only. A Parallel Existence variant that lets Veldora and his power exist at once inside Rimuru and in the outside world; can be undone with Veldora''s consent.', 'https://tensura.fandom.com/wiki/Veldora_(skill)', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('velgrynd_skill', 'Velgrynd (skill)', 'Velgrynd (skill)', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Scorch','Lord of the Flame']::text[], 'Game-only. Same idea as the Veldora skill, linked to Velgrynd.', 'https://tensura.fandom.com/wiki/Velgrynd_(skill)', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('villain', 'Villain', 'Villain', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Scary Person','Villainous Face','Wicked Scoundrel']::text[], 'Works like Chosen One, activating on its own: gives the user a conqueror''s aura so that others read their actions as dominant, making them a natural ruler.', 'https://tensura.fandom.com/wiki/Villain', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('voice_cannon', 'Voice Cannon', 'Voice Cannon', 'common', 'Common skill / Intrinsic skill', ARRAY['Common']::text[], 'Main story', false, '{}'::text[], 'Fires blasts of concentrated sound from shouts, roars or howls, strong enough to make small craters and atomise weak targets.', 'https://tensura.fandom.com/wiki/Voice_Cannon', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('voracious_resurrection', 'Voracious Resurrection', 'Voracious Resurrection', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Devouring Rebirth']::text[], 'Resurrects the user''s children after the user eats their corpses; faster when boosted by Alternative. Similar to Motherly Queen.', 'https://tensura.fandom.com/wiki/Voracious_Resurrection', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('water_blade', 'Water Blade', 'Water Blade', 'common', 'Art / Common skill', ARRAY['Common']::text[], 'Main story', false, ARRAY['Aqua Blade']::text[], 'Sprays magicule-infused, rotating water at high speed as a thin cutting blade that deals physical damage.', 'https://tensura.fandom.com/wiki/Water_Blade', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('water_current_motion', 'Water Current Motion', 'Water Current Motion', 'common', 'Art / Common skill', ARRAY['Common']::text[], 'Main story', false, ARRAY['Current Movement','Water Movement']::text[], 'Creates and freely controls water currents (Rimuru found it by oscillating his body in water).', 'https://tensura.fandom.com/wiki/Water_Current_Motion', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('water_manipulation', 'Water Manipulation', 'Water Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Control Water','Water Control']::text[], 'Manipulates and uses the Water element.', 'https://tensura.fandom.com/wiki/Water_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('weather_domination', 'Weather Domination', 'Weather Domination', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Dominate Weather']::text[], 'Stronger Weather Manipulation giving absolute control over weather.', 'https://tensura.fandom.com/wiki/Weather_Domination', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('weather_manipulation', 'Weather Manipulation', 'Weather Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Control Weather']::text[], 'Manipulates the weather.', 'https://tensura.fandom.com/wiki/Weather_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('wind_manipulation', 'Wind Manipulation', 'Wind Manipulation', 'extra', 'Extra skill', ARRAY['Extra']::text[], 'Main story', false, ARRAY['Control Wind']::text[], 'Manipulates and uses the Wind element, e.g. changing local air pressure to create gusts.', 'https://tensura.fandom.com/wiki/Wind_Manipulation', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('wisher', 'Wisher', 'Wisher', 'unique', 'Unique skill', ARRAY['Unique']::text[], 'Main story', false, ARRAY['Dreamer']::text[], 'Lets the user see the shape of souls and judge a person''s true nature and intentions.', 'https://tensura.fandom.com/wiki/Wisher', 'Wiki API fetch 2026-10-15 (skill pages)', true),
  ('world_map', 'World Map', 'World Map', 'ultimate', 'Ultimate enchantment', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Topography','Lord of Terrain']::text[], 'Awareness of any place in the universe with instant coordinates and real-time projections, even of the whole planet.', 'https://tensura.fandom.com/wiki/World_Map', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('yaoyorozu', 'Yaoyorozu', 'Yaoyorozu', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Shrine Maiden of Guidance']::text[], 'Called a child of Shub-Niggurath: the culmination of Rimuru''s copied skills, an ultimate support ability that guides and reinforces others.', 'https://tensura.fandom.com/wiki/Yaoyorozu', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('yog_sothoth', 'Yog-Sothoth', 'Yog-Sothoth', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['Lord of Spacetime']::text[], 'No ability text on the wiki page; see Yog-Sotohort for its evolved form.', 'https://tensura.fandom.com/wiki/Yog-Sothoth', 'Wiki API fetch 2026-10-15 (skill pages)', false),
  ('yog_sotohort', 'Yog-Sotohort', 'Yog-Sotohort', 'ultimate', 'Ultimate skill', ARRAY['Ultimate']::text[], 'Main story', false, ARRAY['God of the Space-Time','Yog-Sohort','Yog-Sohortz']::text[], 'Sends the user''s memories to the past, giving a kind of precognition at no present cost; unusable during Time Stop. Full abilities unknown.', 'https://tensura.fandom.com/wiki/Yog-Sotohort', 'Wiki API fetch 2026-10-15 (skill pages)', false);
