  ('body.swap.rules', '[{"item": "First fusion into a new body", "rule": "Large magicule cost to tune magic circuits to the new body", "value": "High", "source": "Your text"}, {"item": "Later switching in/out and repairs", "rule": "Very low mana cost (like leaving an app running in the background)", "value": "Low", "source": "Your text"}, {"item": "Body destroyed", "rule": "Soul takes damage and energy drops; the spirit is pulled back to its core (sacred tree, soul space, Rimuru''s stomach) and rests there", "value": "Recovery: a few hours to several days (depends on remaining mana)", "source": "Your text; not in canon as numbers"}, {"item": "Fixed cooldown", "rule": "None: the real limit is magicule recovery", "value": "No timer", "source": "Your text: canon gives no timer"}, {"item": "Cooldown, high regen (Devil lord / Diablo-class, high Dryad)", "rule": "Can build a new projection or move into a new doll almost at once", "value": "Almost instant (mana plentiful)", "source": "Your text: canon gives no numbers"}, {"item": "Cooldown, low regen (lower daemon with no mana left)", "rule": "Needs recovery time", "value": "Hours to several days of rest in the core", "source": "Your text: canon gives no numbers"}]'::jsonb, 'Cost / cooldown notes from Body_Swap sheet (no canon numbers)');
insert into slime_spirit_rules (line, topic, home_area, without_body, with_body, difficulty, source) values
  ('Daemon', 'Needs a material body to stay permanently in the Central World; otherwise rejected back to the Daemon Realm', 'Daemon Realm (they arise there as lesser daemons)', 'Stay in own area; can use a temporary ''magic body'' made of magicules when summoned: physical attacks nearly useless, strong magic resistance. Disembodied energy has a cap, reached at Archdaemon.', 'Can stay permanently; energy limit easier to break, so evolution past Archdaemon (Daemon lord, Devil lord) becomes possible. Physical attacks can hurt; natural effects (e.g. elementals) are especially effective.', 'Hard', 'Wiki (Daemon page) + Your design rule'),
  ('Daemon', 'Corpse fuel while bodiless in the material world', '-', 'One adult human corpse sustains a greater daemon ~3 days or an archdaemon ~1.5 days (wiki). Good survival mechanic.', '-', '-', 'Wiki (fetched)'),
  ('Daemon', 'Ways to get a body (intrinsic skills)', '-', 'Intrinsic skills: Magic Resistance, Material Creation, Possess. Possess is the obvious ''find a body'' hook.', '-', '-', 'Wiki (fetched)'),
  ('Angel', 'Needs a material body to stay long; without one energy leaks (see Spirit_Fuel)', 'Angel realm / heaven (home area not yet verified)', 'Stay in own area; spiritual form', 'Material body unlocks permanent presence; limits TBD', 'Hard', 'Your design rule / Series knowledge - VERIFY'),
  ('Elemental', 'Can stay without a body as long as natural mana of its element exists (see Spirit_Fuel)', 'Spirit realm (home area not yet verified)', 'Stay in own area; wiki says elementals counter daemons', 'Material body unlocks permanent presence; limits TBD', 'Hard', 'Your design rule / Series knowledge - VERIFY'),
  ('Pixie', 'Can stay without a body on ambient mana (see Spirit_Fuel)', 'Fairy home (not verified)', 'Stay in own area', 'TBD', 'Hard', 'Your design rule / Series knowledge - VERIFY'),
  ('Dryad', 'Bound to its tree body; a mobile body (doll) lets it leave the forest (see Body_Acquisition)', 'Tied to the Dryas tree / forest (not verified)', 'Stay in own area', 'TBD', 'Hard', 'Your design rule / Series knowledge - VERIFY'),
  ('Note: the wiki does NOT say a material body protects daemons from spiritual attacks. It says the opposite for physical damage: a magic body makes physical attacks near-useless, and a flesh body loses that benefit.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('All spirit lines', 'Getting a body', '-', 'Four routes: artificial body, possess a corpse/vessel, share a host''s body, self-materialise (max stage only). Body swap allowed. See Body_Acquisition and Body_Swap.', '-', '-', 'Your rules'),
  ('All spirit lines', 'Time limit / fuel outside the home area', '-', 'Daemons: corpses (wiki numbers). Angels: decay timer up to ~1 month. Elementals / Dryads: unlimited while mana/forest lasts. True Dragons: unlimited. See Spirit_Fuel.', '-', '-', 'Your rules + Wiki');
insert into slime_spirit_lines (line, home_area, steps_to_max, self_create_unlock_at, note) values
  ('Angel', 'Angel realm / heaven (home area not yet verified)', 6, 'Seraph', 'Chain Angel -> Power -> Virtue -> Dominion -> Throne -> Cherub -> Seraph (order inferred)'),
  ('Daemon', 'Daemon Realm (they arise there as lesser daemons)', 6, 'Devil lord (Divine devil also counts)', 'Per your text a Devil lord or Divine devil can create a flesh body at once'),
  ('Elemental', 'Spirit realm (home area not yet verified)', 5, 'Elemental lord (flame / land / wind)', 'Lesser -> Medium -> Greater -> Lord'),
  ('Pixie', 'Fairy home (not verified)', 1, 'Chatty pixie', 'Only evolution listed'),
  ('Dryad', 'Tied to the Dryas tree / forest (not verified)', 0, 'Has a tree body from birth', 'Bound to its tree; needs a Dryas doll to leave the forest');
insert into slime_spirit_fuel (stage, fuel, days_min, days_max, unlimited, mode, fails_when, source) values
  ('Greater daemon', '1 adult human corpse', 3.0, 3.0, false, 'Timer per fuel unit', 'Corpses run out: pushed back to the Daemon Realm', 'Wiki (Daemon page)'),
  ('Archdaemon', '1 adult human corpse', 1.5, 1.5, false, 'Timer per fuel unit', 'Corpses run out: pushed back to the Daemon Realm', 'Wiki (Daemon page)'),
  ('Lesser daemon', '1 adult human corpse', 7.0, 14.0, false, 'Timer per fuel unit', 'Corpses run out: pushed back to the Daemon Realm', 'Your pasted text - not verified against the wiki (~1 week, up to 10-14 days if not fighting hard). Fits the wiki trend that lower rank lasts longer per corpse.'),
  ('Angel (all ranks)', 'None: energy leaks away', 3.0, 30.0, false, 'Decay timer, longer for higher grade', 'Energy exhausted: withdraws / fades', 'Your text: lowest-rank / placeholder angels last 3 days to 1 week; higher grades longer, up to ~1 month. Min = 3 (confirmed). Not verified against the wiki.'),
  ('Angels, mass descent (Tenma War)', 'None: energy leaks away', 30.0, 30.0, false, 'Decay timer', 'Energy exhausted: must retreat', 'Your rule (the Tenma War exists in the series; the ''every 500 years'' and ''one month'' details are not confirmed)'),
  ('Elemental', 'Ambient natural mana', NULL, NULL, true, 'Mana-fed', 'No mana of its element, or a mana-sealed zone: weakens and disperses', 'Your rule'),
  ('Dryad', 'Healthy forest', NULL, NULL, true, 'Forest-fed', 'Tied to the forest: fails if the forest is destroyed', 'Your rule'),
  ('True Dragon', 'Self-sustaining', NULL, NULL, true, 'Unlimited', 'Never (a body only helps contain energy leakage)', 'Your rule'),
  ('Pixie', 'Ambient natural mana', NULL, NULL, true, 'Mana-fed', 'Inside a completely mana-free zone', 'Your pasted text - not verified against the wiki. Note: the wiki list files Pixie under Fairies, not Elementals; treat as a game rule.');
insert into slime_body_methods (id, method, how, stability, examples, limits, source) values
  (1, 'Artificial body (Homunculus / Magisteel doll)', 'Build a body from high-grade material (magisteel, magicule slime), then the spirit possesses and fuses with it. Can be customised.', 'Very high (5/6)', 'Rimuru building bodies for others; the Dryads got dolls so they can leave the forest (wiki species list has ''Dryas doll dryad''); Veldora later used a clone body made via Rimuru', 'Needs a skilled maker and rare material', 'Your text; Dryas doll confirmed on the wiki (doll carved from the dryad''s tree body, chaos core doubles energy). The ''pseudo soul / Sarion homunculus tech'' part is not confirmed.'),
  (2, 'Possess a corpse or living vessel', 'Take over a fresh corpse or a weak-willed living creature. Daemons have Possess as an intrinsic skill (wiki).', 'Low-medium (2/6)', 'Emergency summoning cases', 'Corpse decays; power capped by the host body', 'Your text + Wiki (Possess skill)'),
  (3, 'Share a body (symbiosis)', 'Live inside a willing host and lend power, appearing as a projection at times.', 'Medium (3/6)', 'Veldora inside Rimuru''s stomach; Shizu sharing with Ifrit', 'Not fully free to move; depends on the host', 'Your text'),
  (4, 'Self-materialisation / evolution', 'A high-stage spirit builds its own flesh (True Demon Lord awakening, True Dragon re-condensing magicules).', 'Perfect (6/6)', 'True Dragons rebuilding a body; Diablo after the Harvest Festival', 'Needs miracle-level conditions or top evolution stage', 'Your text');
